#include <algorithm>
#include <array>
#include <bitset>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <vector>
#ifndef SIDE
#define SIDE 43
#endif
#ifndef TASK_DEPTH
#define TASK_DEPTH 20
#endif
namespace pg {
constexpr int V=SIDE;using Line=std::array<int,3>;using Mask=unsigned __int128;
struct Counts{uint64_t states=0,attempted=0,structural=0,c8=0,c16=0,accepted=0,rootprune=0,completions=0;Counts&operator+=(const Counts&o){states+=o.states;attempted+=o.attempted;structural+=o.structural;c8+=o.c8;c16+=o.c16;accepted+=o.accepted;rootprune+=o.rootprune;completions+=o.completions;return *this;} static Counts diff(const Counts&a,const Counts&b){Counts d;d.states=a.states-b.states;d.attempted=a.attempted-b.attempted;d.structural=a.structural-b.structural;d.c8=a.c8-b.c8;d.c16=a.c16-b.c16;d.accepted=a.accepted-b.accepted;d.rootprune=a.rootprune-b.rootprune;d.completions=a.completions-b.completions;return d;}};
struct Writer{FILE*f;uint64_t bytes=0;Writer(const char*p,int worker,int W){f=fopen(p,"wb");if(!f){perror(p);exit(90);}unsigned char h[9]={'E','G','P','S',1,(unsigned char)V,(unsigned char)TASK_DEPTH,(unsigned char)W,(unsigned char)worker};if(fwrite(h,1,9,f)!=9)exit(91);bytes=9;}void raw(unsigned char x){if(fputc(x,f)==EOF)exit(91);bytes++;}void u64(uint64_t x){for(int i=0;i<8;i++)raw((unsigned char)(x>>(8*i)));}void record(uint64_t id,const Counts&c){raw('T');u64(id);u64(c.states);u64(c.attempted);u64(c.structural);u64(c.c8);u64(c.c16);u64(c.accepted);u64(c.completions);}void finish(){raw('E');if(fclose(f))exit(91);f=nullptr;}~Writer(){if(f)fclose(f);}};
struct B{std::vector<Line>L;std::array<std::vector<int>,V>inc;std::array<int,V>deg{};std::array<std::bitset<V>,V>pair{};std::array<std::array<int,V>,V>pb;int introduced=10;Counts prefix,sub;uint64_t task_count=0,assigned=0;int worker,W;Writer&w;B(int ww,int WWW,Writer&wr):worker(ww),W(WWW),w(wr){for(auto&r:pb)r.fill(-1);} void add(Line e){int id=L.size();L.push_back(e);for(int x:e){deg[x]++;inc[x].push_back(id);}for(int i=0;i<3;i++)for(int j=i+1;j<3;j++){pair[e[i]].set(e[j]);pair[e[j]].set(e[i]);pb[e[i]][e[j]]=pb[e[j]][e[i]]=id;}} void rem(){auto e=L.back();L.pop_back();for(int x:e){deg[x]--;inc[x].pop_back();}for(int i=0;i<3;i++)for(int j=i+1;j<3;j++){pair[e[i]].reset(e[j]);pair[e[j]].reset(e[i]);pb[e[i]][e[j]]=pb[e[j]][e[i]]=-1;}} bool bad(Line e,int old)const{for(int x:e)if(x<old&&deg[x]>=3)return true;for(int i=0;i<3;i++)for(int j=i+1;j<3;j++)if(e[i]<old&&e[j]<old&&pair[e[i]].test(e[j]))return true;return false;} bool c8(Line e)const{for(int a=0;a<3;a++)for(int b=a+1;b<3;b++){int x=e[a],y=e[b];for(int ai:inc[x])for(int u:L[ai]){if(u==x||u==y)continue;for(int ci:inc[y]){if(ci==ai)continue;for(int v:L[ci]){if(v==x||v==y||v==u)continue;int bi=pb[u][v];if(bi>=0&&bi!=ai&&bi!=ci)return true;}}}}return false;} bool p7(int cur,int tar,int d,Mask sp,Mask sb)const{if(d==7)return cur==tar;if(cur==tar)return false;for(int id:inc[cur]){Mask bm=Mask(1)<<id;if(sb&bm)continue;for(int nx:L[id]){if(nx==cur)continue;Mask pm=Mask(1)<<nx;if(sp&pm)continue;if(nx==tar&&d+1!=7)continue;if(p7(nx,tar,d+1,sp|pm,sb|bm))return true;}}return false;} bool c16(Line e,std::array<std::array<signed char,V>,V>&ca)const{for(int i=0;i<3;i++)for(int j=i+1;j<3;j++){int a=e[i],b=e[j];auto&z=ca[a][b];if(z<0){bool r=p7(a,b,0,Mask(1)<<a,0);z=ca[b][a]=(signed char)r;}if(z)return true;}return false;} static std::array<int,10> mp(int t){std::array<int,10>m{};bool f=t>=5;int r=f?t-5:t;for(int i=0;i<5;i++)m[i]=f?((r-i)%5+5)%5:(i+r)%5;for(int i=0;i<5;i++){int a=m[i],b=m[(i+1)%5];for(int q=0;q<5;q++)if((a==q&&b==(q+1)%5)||(b==q&&a==(q+1)%5)){m[5+i]=5+q;break;}}return m;} std::array<int,10> key(int t)const{auto m=mp(t);std::array<int,5>inv{};for(int i=0;i<5;i++)inv[m[i]]=i;std::array<int,5>cid{};for(int i=0;i<5;i++){cid[i]=-1;for(int id:inc[i])if(id>=5){cid[i]=id;break;}}std::array<int,V>pat{};for(int ns=0;ns<5;ns++){int os=inv[ns];for(int x:L[cid[os]])if(x>=10)pat[x]|=1<<ns;}std::array<int,10>k{};int z=0;for(int ns=0;ns<5;ns++){int os=inv[ns],a=999,b=999;for(int x:L[cid[os]])if(x!=os){int q=x<10?32+m[x]:pat[x];if(q<a){b=a;a=q;}else b=q;}k[z++]=a;k[z++]=b;}return k;} bool canon()const{auto a=key(0);for(int t=1;t<10;t++)if(key(t)<a)return false;return true;} void task_rec(int p,int lq,int lr){sub.states++;while(p<introduced&&deg[p]==3){p++;lq=lr=-1;}if(p>=introduced){if((int)L.size()==introduced)sub.completions++;return;}if((int)L.size()>=V)return;std::array<std::array<signed char,V>,V>ca;for(auto&r:ca)r.fill(-1);int old=introduced;std::vector<int>vs;for(int q=p+1;q<old;q++)if(deg[q]<3&&!pair[p].test(q))vs.push_back(q);if(old<V)vs.push_back(old);if(old+1<V)vs.push_back(old+1);for(size_t i=0;i<vs.size();i++)for(size_t j=i+1;j<vs.size();j++){int q=vs[i],r=vs[j];if(r==old+1&&q!=old)continue;if(lq>=0&&(q<lq||(q==lq&&r<=lr)))continue;sub.attempted++;Line e{p,q,r};unsigned o;if(bad(e,old)){sub.structural++;o=0;}else if(c8(e)){sub.c8++;o=1;}else if(c16(e,ca)){sub.c16++;o=2;}else{sub.accepted++;o=3;}if(o==3){int nx=old;if(q==old||r==old)nx++;if(r==old+1)nx++;int sv=introduced;introduced=nx;add(e);task_rec(p,q,r);rem();introduced=sv;}}} void prefix_rec(int p,int lq,int lr,bool oriented){while(p<introduced&&deg[p]==3){p++;lq=lr=-1;}bool counted=false;if(!oriented&&p>=5){prefix.states++;counted=true;if(!canon()){prefix.rootprune++;return;}oriented=true;} if(oriented&&(int)L.size()>=TASK_DEPTH){uint64_t id=task_count++;if((int)(id%W)==worker){assigned++;Counts before=sub;task_rec(p,lq,lr);w.record(id,Counts::diff(sub,before));}return;} if(!counted)prefix.states++;if(p>=introduced){if((int)L.size()==introduced)prefix.completions++;return;}if((int)L.size()>=V)return;std::array<std::array<signed char,V>,V>ca;for(auto&r:ca)r.fill(-1);int old=introduced;std::vector<int>vs;for(int q=p+1;q<old;q++)if(deg[q]<3&&!pair[p].test(q))vs.push_back(q);if(old<V)vs.push_back(old);if(old+1<V)vs.push_back(old+1);for(size_t i=0;i<vs.size();i++)for(size_t j=i+1;j<vs.size();j++){int q=vs[i],r=vs[j];if(r==old+1&&q!=old)continue;if(lq>=0&&(q<lq||(q==lq&&r<=lr)))continue;prefix.attempted++;Line e{p,q,r};int o;if(bad(e,old)){prefix.structural++;o=0;}else if(c8(e)){prefix.c8++;o=1;}else if(c16(e,ca)){prefix.c16++;o=2;}else{prefix.accepted++;o=3;}if(o==3){int nx=old;if(q==old||r==old)nx++;if(r==old+1)nx++;int sv=introduced;introduced=nx;add(e);prefix_rec(p,q,r,oriented);rem();introduced=sv;}}} void run(){add({0,1,5});add({1,2,6});add({2,3,7});add({3,4,8});add({0,4,9});prefix_rec(0,-1,-1,false);w.finish();}};}
int main(int argc,char**argv){if(argc!=4){fprintf(stderr,"usage: %s WORKER W OUT\n",argv[0]);return 64;}int worker=atoi(argv[1]),W=atoi(argv[2]);if(worker<0||worker>=W||W<1||W>255)return 64;pg::Writer w(argv[3],worker,W);pg::B b(worker,W,w);auto st=std::chrono::steady_clock::now();b.run();double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count();auto&p=b.prefix;auto&s=b.sub;printf("V=%d D=%d worker=%d W=%d tasks=%llu assigned=%llu PREFIX states=%llu attempted=%llu structural=%llu c8=%llu c16=%llu accepted=%llu rootprune=%llu completions=%llu SUB states=%llu attempted=%llu structural=%llu c8=%llu c16=%llu accepted=%llu completions=%llu bytes=%llu seconds=%.6f\n",pg::V,TASK_DEPTH,worker,W,(unsigned long long)b.task_count,(unsigned long long)b.assigned,(unsigned long long)p.states,(unsigned long long)p.attempted,(unsigned long long)p.structural,(unsigned long long)p.c8,(unsigned long long)p.c16,(unsigned long long)p.accepted,(unsigned long long)p.rootprune,(unsigned long long)p.completions,(unsigned long long)s.states,(unsigned long long)s.attempted,(unsigned long long)s.structural,(unsigned long long)s.c8,(unsigned long long)s.c16,(unsigned long long)s.accepted,(unsigned long long)s.completions,(unsigned long long)w.bytes,sec);return (p.completions||s.completions)?2:0;}
